    async def list_thread(
        self,
        message_id: MessageId,
        *,
        limit: typing.Optional[int] = None,
        cursor: typing.Optional[str] = None,
        order: typing.Optional[MessageListThreadOrder] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> AsyncPager[Message, MessageListThreadResponse]:
        """
        Given any message in an iMessage reply thread, returns the original message and every reply, including replies that are still sending. Reactions are never part of a thread.

        A message that isn't in a thread, or a reaction, returns only itself. One request covers at most the 1,000 nearest messages in the thread, in the order you ask for.

        Parameters
        ----------
        message_id : MessageId

        limit : typing.Optional[int]
            Maximum number of items to return.

        cursor : typing.Optional[str]
            The `next_cursor` value from the previous page. Leave it out to get the first page.

        order : typing.Optional[MessageListThreadOrder]
            Oldest first (`asc`, the default) or newest first (`desc`).

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        AsyncPager[Message, MessageListThreadResponse]
            A page of messages in the thread.
        """
        _response = await self._client_wrapper.httpx_client.request(
            f"v1/messages/{encode_path_param(message_id)}/thread",
            method="GET",
            params={
                "limit": limit,
                "cursor": cursor,
                "order": order,
            },
            request_options=request_options,
        )
        try:
            if 200 <= _response.status_code < 300:
                _parsed_response = typing.cast(
                    MessageListThreadResponse,
                    construct_type(
                        type_=MessageListThreadResponse,  # type: ignore
                        object_=_response.json(),
                    ),
                )
                _items = _parsed_response.data.data if _parsed_response.data is not None else []

                _has_next = False
                _get_next = None
                if _parsed_response.data is not None:
                    _parsed_next = _parsed_response.data.next_cursor
                    _has_next = _parsed_next is not None and _parsed_next != ""

                    async def _get_next():
                        return await self.list_thread(
                            message_id,
                            limit=limit,
                            cursor=_parsed_next,
                            order=order,
                            request_options=request_options,
                        )

                return AsyncPager(has_next=_has_next, items=_items, get_next=_get_next, response=_parsed_response)
            if _response.status_code == 400:
                raise BadRequestError(
                    headers=dict(_response.headers),
                    body=typing.cast(
                        ErrorEnvelope,
                        construct_type(
                            type_=ErrorEnvelope,  # type: ignore
                            object_=_response.json(),
                        ),
                    ),
                )
            if _response.status_code == 401:
                raise UnauthorizedError(
                    headers=dict(_response.headers),
                    body=typing.cast(
                        ErrorEnvelope,
                        construct_type(
                            type_=ErrorEnvelope,  # type: ignore
                            object_=_response.json(),
                        ),
                    ),
                )
            if _response.status_code == 404:
                raise NotFoundError(
                    headers=dict(_response.headers),
                    body=typing.cast(
                        ErrorEnvelope,
                        construct_type(
                            type_=ErrorEnvelope,  # type: ignore
                            object_=_response.json(),
                        ),
                    ),
                )
            if _response.status_code == 429:
                raise TooManyRequestsError(
                    headers=dict(_response.headers),
                    body=typing.cast(
                        ErrorEnvelope,
                        construct_type(
                            type_=ErrorEnvelope,  # type: ignore
                            object_=_response.json(),
                        ),
                    ),
                )
            if _response.status_code == 500:
                raise InternalServerError(
                    headers=dict(_response.headers),
                    body=typing.cast(
                        ErrorEnvelope,
                        construct_type(
                            type_=ErrorEnvelope,  # type: ignore
                            object_=_response.json(),
                        ),
                    ),
                )
            _response_json = _response.json()
        except JSONDecodeError:
            raise ApiError(status_code=_response.status_code, headers=dict(_response.headers), body=_response.text)
        except ValidationError as e:
            raise ParsingError(
                status_code=_response.status_code, headers=dict(_response.headers), body=_response.json(), cause=e
            )
        raise ApiError(status_code=_response.status_code, headers=dict(_response.headers), body=_response_json)

